<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$u=current_user();$method=$_SERVER['REQUEST_METHOD'];
$settingsInput=$method==='PUT'?input():[];$tenantKeys=['company','email_defaults','campaign_defaults','sending_limits','notification_settings','import_settings','preferences'];if($method==='PUT'&&$u['role']==='MEMBER'&&array_intersect($tenantKeys,array_keys($settingsInput)))throw new ApiError(403,'You do not have permission to change workspace settings.');
if($method==='GET'){$s=db()->prepare('SELECT setting_key,setting_value FROM tenant_settings WHERE tenant_id=?');$s->execute([$u['tenant_id']]);$settings=[];foreach($s->fetchAll() as $r)$settings[$r['setting_key']]=json_decode($r['setting_value'],true);respond(['profile'=>public_user($u),'settings'=>$settings]);}
if($method==='PUT'){require_csrf();$d=input();if(isset($d['profile'])){$profile=(array)$d['profile'];$name=string_value($profile,'name',100);db()->prepare('UPDATE users SET full_name=? WHERE id=? AND tenant_id=?')->execute([$name,$u['id'],$u['tenant_id']]);}if(isset($d['company'])){require_role('OWNER');$company=string_value((array)$d['company'],'name',120);$timezone=string_value((array)$d['company'],'timezone',64);if(!in_array($timezone,DateTimeZone::listIdentifiers(),true))throw new ApiError(422,'Invalid time zone.');db()->prepare('UPDATE tenants SET name=?,timezone=? WHERE id=?')->execute([$company,$timezone,$u['tenant_id']]);}foreach(['email_defaults','campaign_defaults','sending_limits','notification_settings','import_settings','preferences'] as $key){if(array_key_exists($key,$d)){if(!is_array($d[$key]))throw new ApiError(422,"{$key} must be an object.");$json=json_encode($d[$key],JSON_THROW_ON_ERROR);if(strlen($json)>10000)throw new ApiError(422,"{$key} is too large.");db()->prepare('INSERT INTO tenant_settings (tenant_id,setting_key,setting_value,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)')->execute([$u['tenant_id'],$key,$json,$u['id']]);}}audit('settings.updated');respond(['message'=>'Settings saved.']);}throw new ApiError(405,'Method not allowed.');
